--- /dev/null
+++ b/src/test/java/tools/jackson/databind/jsontype/ext/ExternalTypeIdOnContainer1127Test.java
@@ -0,0 +1,140 @@
+package tools.jackson.databind.jsontype.ext;
+
+import java.util.ArrayList;
+import java.util.LinkedHashMap;
+import java.util.List;
+import java.util.Map;
+import java.util.Optional;
+
+import org.junit.jupiter.api.Test;
+
+import com.fasterxml.jackson.annotation.JsonSubTypes;
+import com.fasterxml.jackson.annotation.JsonTypeInfo;
+
+import tools.jackson.databind.ObjectMapper;
+import tools.jackson.databind.exc.InvalidDefinitionException;
+import tools.jackson.databind.testutil.DatabindTestUtil;
+
+import static org.junit.jupiter.api.Assertions.assertThrows;
+
+// [databind#1127]: `@JsonTypeInfo(As.EXTERNAL_PROPERTY)` cannot work on a container-typed
+// (Collection/array/Map) or reference-typed (Optional) property: there is no place to attach
+// the external type-id sibling property. Verify we fail eagerly with a clear definition error
+// (on both read and write sides) instead of a confusing low-level error during processing.
+public class ExternalTypeIdOnContainer1127Test extends DatabindTestUtil
+{
+    static class Foo { public String msg; }
+    static class FooA extends Foo { public String hey; }
+    static class FooB extends Foo { public String whoa; }
+
+    static class ListHolder {
+        public String footype;
+        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME,
+                include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "footype")
+        @JsonSubTypes({ @JsonSubTypes.Type(value = FooA.class, name = "a"),
+                @JsonSubTypes.Type(value = FooB.class, name = "b") })
+        public List<Foo> foo;
+    }
+
+    static class ArrayHolder {
+        public String footype;
+        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME,
+                include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "footype")
+        @JsonSubTypes({ @JsonSubTypes.Type(value = FooA.class, name = "a") })
+        public Foo[] foo;
+    }
+
+    static class MapHolder {
+        public String footype;
+        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME,
+                include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "footype")
+        @JsonSubTypes({ @JsonSubTypes.Type(value = FooA.class, name = "a") })
+        public Map<String, Foo> foo;
+    }
+
+    static class OptionalHolder {
+        public String footype;
+        @JsonTypeInfo(use = JsonTypeInfo.Id.NAME,
+                include = JsonTypeInfo.As.EXTERNAL_PROPERTY, property = "footype")
+        @JsonSubTypes({ @JsonSubTypes.Type(value = FooA.class, name = "a") })
+        public Optional<Foo> foo;
+    }
+
+    private final ObjectMapper MAPPER = newJsonMapper();
+
+    @Test
+    public void testExternalPropertyOnListFailsEagerly() throws Exception {
+        _verifyReadFailure(ListHolder.class,
+                "{'footype':'a','foo':[{'msg':'Hello','hey':'there'}]}");
+    }
+
+    @Test
+    public void testExternalPropertyOnArrayFailsEagerly() throws Exception {
+        _verifyReadFailure(ArrayHolder.class,
+                "{'footype':'a','foo':[{'msg':'Hello','hey':'there'}]}");
+    }
+
+    @Test
+    public void testExternalPropertyOnMapFailsEagerly() throws Exception {
+        _verifyReadFailure(MapHolder.class,
+                "{'footype':'a','foo':{'x':{'msg':'Hello','hey':'there'}}}");
+    }
+
+    @Test
+    public void testExternalPropertyOnReferenceFailsEagerly() throws Exception {
+        _verifyReadFailure(OptionalHolder.class,
+                "{'footype':'a','foo':{'msg':'Hello','hey':'there'}}");
+    }
+
+    // [databind#1127]: same eager failure must apply on serialization side
+
+    @Test
+    public void testExternalPropertyOnListFailsEagerlyOnWrite() throws Exception {
+        ListHolder h = new ListHolder();
+        h.foo = new ArrayList<>(List.of(_fooA()));
+        _verifyWriteFailure(h);
+    }
+
+    @Test
+    public void testExternalPropertyOnArrayFailsEagerlyOnWrite() throws Exception {
+        ArrayHolder h = new ArrayHolder();
+        h.foo = new Foo[] { _fooA() };
+        _verifyWriteFailure(h);
+    }
+
+    @Test
+    public void testExternalPropertyOnMapFailsEagerlyOnWrite() throws Exception {
+        MapHolder h = new MapHolder();
+        h.foo = new LinkedHashMap<>();
+        h.foo.put("x", _fooA());
+        _verifyWriteFailure(h);
+    }
+
+    @Test
+    public void testExternalPropertyOnReferenceFailsEagerlyOnWrite() throws Exception {
+        OptionalHolder h = new OptionalHolder();
+        h.foo = Optional.of(_fooA());
+        _verifyWriteFailure(h);
+    }
+
+    private FooA _fooA() {
+        FooA f = new FooA();
+        f.msg = "Hello";
+        f.hey = "there";
+        return f;
+    }
+
+    private void _verifyReadFailure(Class<?> type, String json) {
+        InvalidDefinitionException e = assertThrows(InvalidDefinitionException.class,
+                () -> MAPPER.readValue(a2q(json), type));
+        verifyException(e, "EXTERNAL_PROPERTY");
+        verifyException(e, "container-typed property");
+    }
+
+    private void _verifyWriteFailure(Object value) {
+        InvalidDefinitionException e = assertThrows(InvalidDefinitionException.class,
+                () -> MAPPER.writeValueAsString(value));
+        verifyException(e, "EXTERNAL_PROPERTY");
+        verifyException(e, "container-typed property");
+    }
+}

problem_statement:
`@JsonTypeInfo` with `EXTERNAL_PROPERTY` doesn't handle arrays of polymorphic types

While the JsonFormat.Feature.ACCEPT_SINGLE_VALUE_AS_ARRAY works fine normally, there is an issue when using it along with @JsonTypeInfo and its JsonTypeInfo.As.EXTERNAL_PROPERTY feature (regular PROPERTY works fine).  Below is an example test case to illustrate the issue:

```
    public static class Foo {
        public String msg;
    }

    public static class FooA extends Foo {
        public String hey;
    }

    public static class FooB extends Foo {
        public String whoa;
    }

    public static class Holder {
        public String footype;

        @JsonTypeInfo(use      = JsonTypeInfo.Id.NAME,
                      include  = JsonTypeInfo.As.EXTERNAL_PROPERTY,
                      property = "footype")
        @JsonSubTypes({@JsonSubTypes.Type(value=FooA.class, name="a"),
                       @JsonSubTypes.Type(value=FooB.class, name="b") })
        @JsonFormat(with=JsonFormat.Feature.ACCEPT_SINGLE_VALUE_AS_ARRAY)
        public List<Foo> foo;
        public Foo other;
    }

    @Test
    public void testSVA() throws Exception
    {
        final InputStream stream = TestSingleValueArray.class.getResourceAsStream("footest.json");
        Scanner s = new Scanner(stream);
        final String json = s.useDelimiter("\\Z").next();
        s.close();

        final ObjectMapper mapper = new ObjectMapper();

        final Holder holder = mapper.readValue(json, Holder.class);
    }

```

I expected the above test to combine the external property and array features, but it instead throws the following error:

```
com.fasterxml.jackson.databind.JsonMappingException: Unexpected token (START_OBJECT), expected START_ARRAY: need JSON Array to contain As.WRAPPER_ARRAY type information for class TestSingleValueArray$Foo
 at [Source: {
    "footype": "a",
    "foo": {
        "msg": "Hello World",
        "hey": "there"
    },
    "other": {
        "msg": "Goodbye"
    }
}; line: 3, column: 12] (through reference chain: Holder["foo"]->java.lang.Object[0])
    at com.fasterxml.jackson.databind.JsonMappingException.from(JsonMappingException.java:216)
    at com.fasterxml.jackson.databind.DeserializationContext.wrongTokenException(DeserializationContext.java:962)
    at com.fasterxml.jackson.databind.jsontype.impl.AsArrayTypeDeserializer._locateTypeId(AsArrayTypeDeserializer.java:127)
    at com.fasterxml.jackson.databind.jsontype.impl.AsArrayTypeDeserializer._deserialize(AsArrayTypeDeserializer.java:93)
    at com.fasterxml.jackson.databind.jsontype.impl.AsArrayTypeDeserializer.deserializeTypedFromObject(AsArrayTypeDeserializer.java:58)
    at com.fasterxml.jackson.databind.deser.BeanDeserializerBase.deserializeWithType(BeanDeserializerBase.java:1017)
    at com.fasterxml.jackson.databind.deser.std.CollectionDeserializer.handleNonArray(CollectionDeserializer.java:341)
    at com.fasterxml.jackson.databind.deser.std.CollectionDeserializer.deserialize(CollectionDeserializer.java:259)
    at com.fasterxml.jackson.databind.deser.std.CollectionDeserializer.deserialize(CollectionDeserializer.java:249)
    at com.fasterxml.jackson.databind.deser.std.CollectionDeserializer.deserialize(CollectionDeserializer.java:26)
    at com.fasterxml.jackson.databind.deser.SettableBeanProperty.deserialize(SettableBeanProperty.java:490)
    at com.fasterxml.jackson.databind.deser.impl.FieldProperty.deserializeAndSet(FieldProperty.java:101)
    at com.fasterxml.jackson.databind.deser.BeanDeserializer.vanillaDeserialize(BeanDeserializer.java:260)
    at com.fasterxml.jackson.databind.deser.BeanDeserializer.deserialize(BeanDeserializer.java:125)
    at com.fasterxml.jackson.databind.ObjectMapper._readMapAndClose(ObjectMapper.java:3788)
    at com.fasterxml.jackson.databind.ObjectMapper.readValue(ObjectMapper.java:2779)
    at TestSingleValueArray.testSVA(TestSingleValueArray.java:63)
```

Here is the input used to produce the above error:

```
{
    "footype": "a",
    "foo": {
        "msg": "Hello World",
        "hey": "there"
    },
    "other": {
        "msg": "Goodbye"
    }
}
```

Moving the footype field into Foo and switching from EXTERNAL_PROPERTY to a plain PROPERTY fixes the error, but of course is not quite the same.

Thanks in advance for your help!
